+				"app/build.gradle":             "",
+				"lib/build.gradle":             "",
+				"lib/src/main/java/A.java":     "",
+				"lib/src/test/java/ATest.java": "",
+			}
+			if tc.rootBuild {
+				files["build.gradle"] = ""
+			}
+			results := []SearchResult{
+				{Rank: 1, FilePath: "lib/src/main/java/A.java", Section: searchSectionPrimary},
