+			wantDerivedFrom := "repository evidence did not establish a safe verification command"
+			if got.DerivedFrom != wantDerivedFrom {
+				t.Fatalf("derived from = %q, want %q", got.DerivedFrom, wantDerivedFrom)
+			}
+		})
+	}
+}
